import path from 'node:path';
export function uploadDestination(root: string, input: string) {
  if (path.isAbsolute(input)) throw new Error('absolute');
  const normalized = path.normalize(input);
  if (normalized === '..' || normalized.startsWith(`..${path.sep}`)) throw new Error('traversal');
  const destination = path.resolve(root, normalized);
  if (!destination.startsWith(`${path.resolve(root)}${path.sep}`)) throw new Error('outside root');
  return destination;
}
